from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.core.extern import Extern, _EErr


class _Sqrt(Extern):
    def __init__(self):
        # Exo-level name used in expressions: sqrt(...)
        super().__init__("sqrt")

    def typecheck(self, args):
        if len(args) != 1:
            raise _EErr(f"expected 1 argument, got {len(args)}")

        arg_type = args[0].type
        if not arg_type.is_real_scalar():
            raise _EErr(
                f"expected argument to be a real scalar value, but got type {arg_type}"
            )
        # sqrt returns the same real scalar type
        return arg_type

    def compile(self, args, prim_type):
        # Use PolyBench's SQRT_FUN macro so we get sqrt/sqrtf consistently
        return f"SQRT_FUN(({prim_type}){args[0]})"

    def globl(self, prim_type):
        # Ensure math header is available in the generated C
        return "#include <math.h>"

    def interpret(self, args):
        import math
        return math.sqrt(args[0])


sqrt = _Sqrt()


@proc
def kernel_cholesky(
    n: size,
    A: DATA_TYPE[n, n] @ DRAM,
):
    for i in seq(0, n):
        # j < i
        for j in seq(0, i):
            for k in seq(0, j):
                # A[i][j] -= A[i][k] * A[j][k];
                # use += with a negated term to express the reduction
                A[i, j] += -A[i, k] * A[j, k]
            # A[i][j] /= A[j][j];
            A[i, j] = A[i, j] / A[j, j]

        # i == j case
        for k in seq(0, i):
            # A[i][i] -= A[i][k] * A[i][k];
            A[i, i] += -A[i, k] * A[i, k]

        # A[i][i] = SQRT_FUN(A[i][i]);
        A[i, i] = sqrt(A[i, i])
EXO END
*/


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, N, N, n, n);

  /* Initialize array(s). */
  init_array (n, POLYBENCH_ARRAY(A));

  /* Start timer. */
  polybench_start_instruments;

  /* Run Exo kernel. Flatten 2D view to 1D pointer. */
  kernel_cholesky (/*ctxt=*/NULL,
                   n,
                   (DATA_TYPE*)POLYBENCH_ARRAY(A));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(A)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);

  return 0;
